      code: "class TrieNode {\n    constructor() {\n        this.children = {}\n        this.isWord = false\n    }\n}\n\nclass Trie {\n    constructor() {\n        this.root = new TrieNode()\n    }\n\n    build(words) {\n        for (const word of words) {\n            this.insert(word)\n        }\n    }\n\n    insert(word) {\n        let node = this.root\n\n        for (const char of word) {\n            if (!(char in node.children)) {\n                node.children[char] = new TrieNode()\n            }\n            node = node.children[char]\n        }\n\n        node.isWord = true\n    }\n\n    search(word) {\n        let node = this.root\n\n        for (const char of word) {\n            if (!(char in node.children)) {\n                return false\n            }\n            node = node.children[char]\n        }\n\n        return node.isWord\n    }\n\n    startsWith(prefix) {\n        let node = this.root\n\n        for (const char of prefix) {\n            if (!(char in node.children)) {\n                return false\n            }\n            node = node.children[char]\n        }\n\n        return true\n    }\n\n    collectWords(node, prefix) {\n        const words = []\n\n        if (node.isWord) {\n            words.push(prefix)\n        }\n\n        for (const [char, childNode] of Object.entries(node.children)) {\n            words.push(...this.collectWords(childNode, prefix + char))\n        }\n\n        return words\n    }\n\n    toString() {\n        return 'Trie:\\n' + this._printTrie(this.root)\n    }\n\n    _printTrie(node, level = 0, prefix = '') {\n        let output = ''\n        const prefixStr = '    '.repeat(level) + prefix\n\n        if (!node) {\n            return output\n        }\n\n        if (node.isWord) {\n            output += prefixStr + ' ├─ ' + '(*)' + '\\n'\n        }\n\n        const children = Object.entries(node.children)\n        children.forEach(([char, childNode], i) => {\n            const isLast = i === children.length - 1\n            const marker = isLast ? '└─ ' : '├─ '\n            output += prefixStr + marker + char + '\\n'\n            output += this._printTrie(childNode, level + 1, isLast ? '     ' : '    │')\n        })\n\n        return output\n    }\n}",
