export function codeTemplatesForLanguage(language: string): CodeTemplate[] {
  const templateLanguage = language as TemplateLanguage;
  return [
    ...(templatesByLanguage[templateLanguage] ?? []),
    ...(supplementalTemplatesByLanguage[templateLanguage] ?? []),
  ];
}
